#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHTML(const std::string& markdown) {
    std::string html;
    std::stringstream stream(markdown);

    while (stream) {
        std::string line;
        std::getline(stream, line);

        // Add HTML tags to each line
        html += "<p>" + line + "</p>\n";
    }

    return html;
}

int main() {
    std::string markdown = "# Hello World\nThis is a paragraph.\n\nThis is another paragraph.";
    std::string html = markdownToHTML(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

